package com.orderflow.scheduler;

import static org.assertj.core.api.Assertions.assertThat;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import java.time.*;import java.util.List;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.Container;import org.testcontainers.junit.jupiter.Testcontainers;
@Testcontainers class PostgresJobSchedulerIT{@Container static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:16-alpine");static JdbcTemplate jdbc;@BeforeAll static void schema(){jdbc=new JdbcTemplate(new DriverManagerDataSource(POSTGRES.getJdbcUrl(),POSTGRES.getUsername(),POSTGRES.getPassword()));jdbc.execute("CREATE TABLE scheduled_job_lock(job_name varchar primary key,locked_until timestamptz not null,locked_at timestamptz,locked_by varchar,last_started_at timestamptz,last_completed_at timestamptz,last_status varchar,last_duration_ms bigint,failure_count bigint not null default 0,last_error_code varchar,updated_at timestamptz not null)");}@Test void concurrentInstancesHaveOneWinnerAndExpiredLeaseRecovers()throws Exception{Instant now=Instant.parse("2026-08-19T00:00:00Z");var a=scheduler("a");var b=scheduler("b");try(var executor=Executors.newVirtualThreadPerTaskExecutor()){List<Future<Boolean>> results=List.of(executor.submit(()->a.acquire("job",Duration.ofSeconds(30),now)),executor.submit(()->b.acquire("job",Duration.ofSeconds(30),now)));assertThat(results.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);}assertThat(b.acquire("job",Duration.ofSeconds(30),now.plusSeconds(31))).isTrue();}private PostgresJobScheduler scheduler(String id){return new PostgresJobScheduler(jdbc,new SchedulerSupportProperties(id),new SimpleMeterRegistry(),Clock.systemUTC(),"test-service");}}
